19	import { describe, it, expect, vi, afterEach } from "vitest";
20	import {
21	  mkdtempSync,
22	  mkdirSync,
23	  writeFileSync,
24	  readFileSync,
25	  rmSync,
26	} from "node:fs";
27	import { tmpdir } from "node:os";
28	import { join } from "node:path";
29	import { execSync, spawnSync } from "node:child_process";
30	import { stringify as yamlStringify, parse as parseYaml } from "yaml";
31	import type { Task } from "../src/types/task.js";
32	import type { ExecutorPortInput } from "@workflow/runtime-abi";
33	import {
34	  dispatchReviewer,
35	  type DispatchReviewerOptions,
36	} from "../src/pr-response/dispatch-reviewer.js";
37	import { FakeBrokerAdapter } from "@workflow/runtime-abi";
38	
39	// ── Mock node:child_process ───────────────────────────────────────────────────
40	
