1	/**
2	 * Integration tests for SubProcessAdapter Wave-3 (T5).
3	 *
4	 * These tests exercise the full async submit → runner callback → broker flow
5	 * using a real InMemoryBrokerAdapter (HTTP server) and a fake runner script
6	 * that simulates each scenario.
7	 *
8	 * Scenarios covered:
9	 *   1. Happy path — fake runner POSTs a valid result; broker.listCompleted delivers it.
10	 *   2. Wrapper crash before POST — runner exits without POSTing; safety net fires
11	 *      a synthetic "failed" completion to the broker.
12	 *   3. Late callback — runner sleeps before POSTing; broker still delivers the result.
13	 *   4. Broker-reject (replay) — runner POSTs twice; second POST (after ack) returns 401;
14	 *      broker.listCompleted is called only once.
15	 *   5. ack() removes supervision entry and cleans up result file.
16	 *   6. submit() returns a non-empty handle string immediately (non-blocking).
17	 */
18	
19	import { describe, it, expect, beforeEach, afterEach } from "vitest";
20	import {
21	  mkdtempSync,
22	  rmSync,
23	  writeFileSync,
24	  existsSync,
25	  writeFile,
26	} from "node:fs";
27	import { join } from "node:path";
28	import { tmpdir } from "node:os";
