36	// ── Helpers ───────────────────────────────────────────────────────────────────
37	
38	const tmpDirs: string[] = [];
39	
40	function makeTmpDir(prefix: string): string {
41	  const dir = mkdtempSync(join(tmpdir(), prefix));
42	  tmpDirs.push(dir);
43	  return dir;
44	}
45	
46	/**
47	 * Poll broker.listCompleted until at least one completion arrives,
48	 * or the timeout expires. Returns the first completion found.
49	 */
50	async function waitForCompletion(
51	  broker: InMemoryBrokerAdapter,
52	  timeoutMs = 10_000,
53	  pollMs = 50,
54	): Promise<ReturnType<typeof broker.listCompleted> extends Promise<(infer T)[]> ? T : never> {
55	  const deadline = Date.now() + timeoutMs;
56	  while (Date.now() < deadline) {
57	    const items = await broker.listCompleted({ max: 1, lockMs: 30_000 });
58	    if (items.length > 0) return items[0] as any;
59	    await new Promise((r) => setTimeout(r, pollMs));
60	  }
61	  throw new Error(`waitForCompletion: no completion arrived within ${timeoutMs}ms`);
62	}
63	
64	/** Build a minimal ExecutorPortInput for tests. */
65	function makeInput(overrides: {
66	  briefingPath?: string;
67	  resultPath: string;
68	  callbackUrl: string;
69	  nonce: string;
70	  handle?: string;
71	  taskId?: string;
72	  featureId?: string;
73	  executorWorkdir?: string;
