77	    featureId: overrides.featureId ?? "runtime-portable-architecture",
78	    workspaceId: "test-ws",
79	    handle: overrides.handle ?? "test-handle-subprocess",
80	    taskRepoUrl: "git@github.com:org/repo.git",
81	    taskRepoBranch: "feature/runtime-portable-architecture-T5",
82	    executorWorkdir: overrides.executorWorkdir ?? "/tmp",
83	    mgmtRepoUrl: "git@github.com:org/workspace.git",
84	    briefingPath: overrides.briefingPath ?? "/tmp/briefing.md",
85	    resultPath: overrides.resultPath,
86	    sshPrivateKey: "",
87	    githubToken: "",
88	    callbackUrl: overrides.callbackUrl,
89	    nonce: overrides.nonce,
90	  };
91	}
