/**
 * Seam tests: orchestrator dispatch + FakeAdapter.
 *
 * These tests exercise the ABI seam — the boundary between the adapter
 * (which produces an ExecutorResult) and the orchestrator's side-effect
 * dispatcher (which translates that result into task YAML mutations).
 *
 * Uses dispatchExecutorResult (extracted from main.ts) so the full
 * bootstrap + poll loop does not need to run.
 *
 * Revised D5: the executor owns impl-PR creation; the orchestrator only
 * records the pr_url reported in result.json. No curl/GitHub API calls are
 * made by the orchestrator for impl PRs.
 *
 * FakeAdapter scenarios:
 *   1. in_review with pr_url → task in_review, pr.url recorded, draft PR promoted to ready-for-review
 *   2. in_review without pr_url → task in_review, no pr.url set, no PATCH call
 *   3. blocked with pr_url → task blocked, pr.url still recorded (draft PR), no PATCH
 *   4. blocked with reason + suggestion → task marked blocked
 *   5. failed with executor_crashed reason → task blocked with executor_failed prefix
 *   6. failed with result_schema_invalid reason → task blocked with executor_failed prefix
 *   7. cost data — in_review with token_usage + cost_usd → run_completed log entry persists cost
 *   8. cost data — in_review without token_usage/cost_usd → run_completed log entry has no cost
 *   9. cost data — blocked with token_usage + cost_usd → blocked log entry persists cost
 *  10. in_review with pr_url, PATCH fails → task_pr_promote_failed emitted, task still in_review
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import {
  createFakeAdapter,
  createInReviewAdapter,
  createBlockedAdapter,
  createFailedAdapter,
} from "@workflow/runtime-abi";
import type { ExecutorInput } from "@workflow/runtime-abi";
import { dispatchExecutorResult } from "../src/side-effects/dispatch.js";

// ── Mock git for dispatch side-effects ────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "seam-test-feature";
const TASK_ID = "T1";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const TASK_TITLE = "Seam test task";
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GITHUB_TOKEN = "ghp_test";
const TASK_REPO_URL = "git@github.com:myorg/impl-repo.git";
const TASK_BASE_BRANCH = "main";

const IMPL_PR_URL = "https://github.com/myorg/impl-repo/pull/99";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: TASK_TITLE,
    repo: "impl-repo",
    status: "in_progress",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task): string {
  const dir = mkdtempSync(join(tmpdir(), "seam-dispatch-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  return dir;
}

function readTask(wsRoot: string): Task {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

function mockGitSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
});

const stubInput: ExecutorInput = {
  taskId: TASK_ID,
  featureId: FEATURE_ID,
  workspaceId: "test-workspace",
  taskRepoUrl: TASK_REPO_URL,
  taskRepoBranch: TASK_BRANCH,
  taskRepoPath: "/tmp/impl-repo",
  briefingPath: "/tmp/briefing.md",
  resultPath: "/tmp/result.json",
  sshPrivateKey: "",
  githubToken: GITHUB_TOKEN,
};

// ── 1. in_review with pr_url from result ─────────────────────────────────────

describe("seam: in_review with pr_url in result", () => {
  it("records pr.url from result.pr_url and promotes draft PR to ready-for-review", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        return {
          pid: 0, output: [], stdout: JSON.stringify({ html_url: IMPL_PR_URL, number: 99, node_id: "PR_nodeid_abc123" }),
          stderr: "", status: 0, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("in_review");
    expect(result.pr_url).toBe(IMPL_PR_URL);

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
    expect(task.log.some((e) => e.action === "run_completed")).toBe(true);

    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(true);
    expect(events.some((e) => e.type === "impl_pr_opened")).toBe(false);
    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(false);

    // Orchestrator promotes the draft PR to ready-for-review via GraphQL (REST GET + mutation)
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(2);
    // Second call is the GraphQL mutation
    const gqlArgs = curlCalls[1][1] as string[];
    expect(gqlArgs).toContain("https://api.github.com/graphql");
    expect((gqlArgs as string[]).some((a) => typeof a === "string" && a.includes("markPullRequestReadyForReview"))).toBe(true);
  });
});

// ── 2. in_review without pr_url ───────────────────────────────────────────────

describe("seam: in_review without pr_url", () => {
  it("task is marked in_review with no pr.url when result carries no pr_url", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createInReviewAdapter();

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("in_review");
    expect(result.pr_url).toBeUndefined();

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    // No pr_url in result → pr.url stays empty
    expect(task.pr.url).toBe("");
    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(false);
    // No curl calls
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── 3. blocked with pr_url — draft PR documents failed attempt ────────────────

describe("seam: blocked with pr_url (draft PR)", () => {
  it("records pr.url on blocked task — draft PR documents failed attempt", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "blocked",
      blocked_reason: "tests_failed",
      pr_url: IMPL_PR_URL,
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("blocked");
    expect(result.pr_url).toBe(IMPL_PR_URL);

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("tests_failed");
    // pr_url recorded even though task is blocked
    expect(task.pr.url).toBe(IMPL_PR_URL);
    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(true);
    // No curl calls
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── 4. blocked with reason + suggestion ──────────────────────────────────────

describe("seam: blocked with reason + suggestion", () => {
  it("FakeAdapter blocked → task status blocked, reason and suggestion written", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createBlockedAdapter("missing_tool", "Install node 20.");

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("blocked");
    expect(result.blocked_reason).toBe("missing_tool");

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("missing_tool");
    expect(task.blocked_suggestion).toBe("Install node 20.");
    expect(task.log.some((e) => e.action === "blocked")).toBe(true);
  });
});

// ── 5. failed → executor_crashed in blocked_reason ───────────────────────────

describe("seam: failed — executor_crashed", () => {
  it("FakeAdapter failed with executor_crashed → task blocked with executor_failed prefix", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "failed",
      blocked_reason: "executor_crashed (exit 1)",
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("failed");

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("executor_failed:executor_crashed (exit 1)");
    expect(task.log.some((e) => e.action === "blocked")).toBe(true);
  });
});

// ── 6. failed → result_schema_invalid in blocked_reason ──────────────────────

describe("seam: failed — result_schema_invalid", () => {
  it("FakeAdapter failed with schema reason → task blocked with executor_failed prefix", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "failed",
      blocked_reason: "result_schema_invalid: must have required property 'terminal_status'",
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(String(task.blocked_reason)).toContain("executor_failed:");
    expect(String(task.blocked_reason)).toContain("result_schema_invalid");
  });
});

// ── 7. cost data — in_review with token_usage + cost_usd ─────────────────────

describe("seam: cost data — in_review with token_usage + cost_usd", () => {
  it("persists token_usage and cost_usd into run_completed log entry", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "in_review",
      pr_url: IMPL_PR_URL,
      token_usage: { input: 45231, output: 3812, model: "claude-sonnet-4-6" },
      cost_usd: 0.19,
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        return {
          pid: 0, output: [], stdout: JSON.stringify({ html_url: IMPL_PR_URL, number: 99, node_id: "PR_nodeid_abc123" }),
          stderr: "", status: 0, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const result = await adapter.run(stubInput);
    expect(result.token_usage).toEqual({ input: 45231, output: 3812, model: "claude-sonnet-4-6" });
    expect(result.cost_usd).toBe(0.19);

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    const runEntry = task.log.find((e) => e.action === "run_completed");
    expect(runEntry).toBeDefined();
    expect(runEntry!.token_usage).toEqual({ input: 45231, output: 3812, model: "claude-sonnet-4-6" });
    expect(runEntry!.cost_usd).toBe(0.19);
  });
});

// ── 8. cost data — in_review without token_usage/cost_usd ────────────────────

describe("seam: cost data — in_review without token_usage/cost_usd", () => {
  it("run_completed log entry has no token_usage or cost_usd when result omits them", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createInReviewAdapter();

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.token_usage).toBeUndefined();
    expect(result.cost_usd).toBeUndefined();

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    const runEntry = task.log.find((e) => e.action === "run_completed");
    expect(runEntry).toBeDefined();
    expect(runEntry).not.toHaveProperty("token_usage");
    expect(runEntry).not.toHaveProperty("cost_usd");
  });
});

// ── 10. in_review with pr_url, PATCH fails → task_pr_promote_failed ──────────

describe("seam: in_review with pr_url — PATCH failure emits task_pr_promote_failed", () => {
  it("emits task_pr_promote_failed when curl PATCH errors; task is still in_review", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        // Network-level failure: empty stdout, non-zero status
        return {
          pid: 0, output: [], stdout: "",
          stderr: "curl: (6) Could not resolve host", status: 1, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(true);
    // PATCH failure is non-fatal — task still transitions to in_review
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
  });

  it("emits task_pr_promote_failed when GitHub returns HTTP 403/422 (--fail exits 22)", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        // --fail causes curl to exit 22 on HTTP 4xx; body is suppressed
        return {
          pid: 0, output: [], stdout: "",
          stderr: "curl: (22) The requested URL returned error: 403",
          status: 22, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(true);
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
  });
});

// ── 11–14. Notifier injection ─────────────────────────────────────────────────

import type { TaskNotifierPort, TaskNotificationEvent } from "../src/ports/task-notifier.port.js";

function makeNotifier(): { notifier: TaskNotifierPort; events: TaskNotificationEvent[]; error?: Error } {
  const events: TaskNotificationEvent[] = [];
  const notifier: TaskNotifierPort = { notify: async (e) => { events.push(e); } };
  return { notifier, events };
}

describe("seam: notifier called on in_review", () => {
  it("calls notifier.notify with in_review event including taskTitle", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createInReviewAdapter();
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const { notifier, events } = makeNotifier();
    const result = await adapter.run(stubInput);
    const emitted: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result, workspaceRoot: wsRoot, featureId: FEATURE_ID, taskId: TASK_ID,
      taskBranch: TASK_BRANCH, taskTitle: TASK_TITLE, taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH, githubToken: "", gitAuthorEmail: GIT_AUTHOR_EMAIL,
      notifier, emit: (e) => emitted.push(e),
    });

    expect(events).toHaveLength(1);
    expect(events[0].type).toBe("in_review");
    expect(events[0].taskTitle).toBe(TASK_TITLE);
    expect(emitted.some((e) => e.type === "task_notification_failed")).toBe(false);
  });

  it("skips notification when notifier is absent", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createInReviewAdapter();
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    // no notifier passed — should complete without error
    await expect(dispatchExecutorResult({
      result, workspaceRoot: wsRoot, featureId: FEATURE_ID, taskId: TASK_ID,
      taskBranch: TASK_BRANCH, taskTitle: TASK_TITLE, taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH, githubToken: "", gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    })).resolves.toBeUndefined();
  });

  it("emits task_notification_failed when notifier throws but task still transitions to in_review", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createInReviewAdapter();
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const failingNotifier: TaskNotifierPort = { notify: async () => { throw new Error("network down"); } };
    const result = await adapter.run(stubInput);
    const emitted: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result, workspaceRoot: wsRoot, featureId: FEATURE_ID, taskId: TASK_ID,
      taskBranch: TASK_BRANCH, taskTitle: TASK_TITLE, taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH, githubToken: "", gitAuthorEmail: GIT_AUTHOR_EMAIL,
      notifier: failingNotifier, emit: (e) => emitted.push(e),
    });

    expect(emitted.some((e) => e.type === "task_notification_failed" && e.event === "in_review")).toBe(true);
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
  });
});

describe("seam: notifier called on blocked", () => {
  it("calls notifier.notify with blocked event including taskTitle and blockedReason", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createBlockedAdapter("missing_tool", "Install node 20.");
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const { notifier, events } = makeNotifier();
    const result = await adapter.run(stubInput);
    const emitted: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result, workspaceRoot: wsRoot, featureId: FEATURE_ID, taskId: TASK_ID,
      taskBranch: TASK_BRANCH, taskTitle: TASK_TITLE, taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH, githubToken: "", gitAuthorEmail: GIT_AUTHOR_EMAIL,
      notifier, emit: (e) => emitted.push(e),
    });

    expect(events).toHaveLength(1);
    expect(events[0].type).toBe("blocked");
    expect(events[0].taskTitle).toBe(TASK_TITLE);
    expect(events[0].blockedReason).toBe("missing_tool");
    expect(emitted.some((e) => e.type === "task_notification_failed")).toBe(false);
  });
});

// ── 9. cost data — blocked with token_usage + cost_usd ───────────────────────

describe("seam: cost data — blocked with token_usage + cost_usd", () => {
  it("persists token_usage and cost_usd into blocked log entry", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "blocked",
      blocked_reason: "tests_failed",
      token_usage: { input: 12000, output: 800, model: "claude-sonnet-4-6" },
      cost_usd: 0.05,
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.token_usage).toEqual({ input: 12000, output: 800, model: "claude-sonnet-4-6" });
    expect(result.cost_usd).toBe(0.05);

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    const blockedEntry = task.log.find((e) => e.action === "blocked");
    expect(blockedEntry).toBeDefined();
    expect(blockedEntry!.token_usage).toEqual({ input: 12000, output: 800, model: "claude-sonnet-4-6" });
    expect(blockedEntry!.cost_usd).toBe(0.05);
  });
});

