import { describe, it, expect } from "vitest";
import {
  createFakeExecutorPort,
  createFakeBriefingTransport,
  createFakeWorkflowState,
  createFakeCredential,
  createFakeWorkspacePull,
  createFakeEventEmitter,
  createFakeScheduler,
  createFakeClock,
} from "../src/fake-ports.js";
import type { ExecutorPortInput } from "../src/types.js";

function fakeInput(taskId = "T1"): ExecutorPortInput {
  return {
    taskId,
    featureId: "test-feature",
    workspaceId: "ws-1",
    taskRepoUrl: "git@github.com:org/repo.git",
    taskRepoBranch: "feature/test",
    taskRepoPath: "/tmp/repo",
    briefingPath: "/tmp/briefing.md",
    resultPath: "/tmp/result.json",
    sshKeyPath: "/fake/key",
    githubToken: "fake-token",
    callbackUrl: "http://127.0.0.1:9000/callback",
    nonce: "test-nonce",
  };
}

// ── FakeExecutorPort ──────────────────────────────────────────────────────────

describe("createFakeExecutorPort", () => {
  it("generates a deterministic handle from taskId", async () => {
    const port = createFakeExecutorPort();
    const h = await port.submit(fakeInput("T1"));
    expect(h).toContain("T1");
  });

  it("records submitted handles in order", async () => {
    const port = createFakeExecutorPort();
    await port.submit(fakeInput("T1"));
    await port.submit(fakeInput("T2"));
    expect(port.submittedHandles).toHaveLength(2);
    expect(port.submittedInputs[0].taskId).toBe("T1");
    expect(port.submittedInputs[1].taskId).toBe("T2");
  });

  it("readResult defaults to in_review", async () => {
    const port = createFakeExecutorPort();
    const result = await port.readResult("some-handle");
    expect(result.terminal_status).toBe("in_review");
  });

  it("accepts custom submit and readResult overrides", async () => {
    const port = createFakeExecutorPort({
      submit: async () => "custom-handle",
      readResult: async () => ({ terminal_status: "blocked", blocked_reason: "test" }),
    });
    expect(await port.submit(fakeInput())).toBe("custom-handle");
    expect((await port.readResult("x")).terminal_status).toBe("blocked");
  });

  it("records handles even with custom submit override", async () => {
    const port = createFakeExecutorPort({ submit: async () => "override" });
    await port.submit(fakeInput("T3"));
    expect(port.submittedHandles).toEqual(["override"]);
  });
});

// ── FakeBriefingTransport ─────────────────────────────────────────────────────

describe("createFakeBriefingTransport", () => {
  it("put records the call and returns a fake path", async () => {
    const bt = createFakeBriefingTransport();
    const path = await bt.put("h1", "briefing content");
    expect(path).toContain("h1");
    expect(bt.putCalls).toHaveLength(1);
    expect(bt.putCalls[0].handle).toBe("h1");
    expect(bt.putCalls[0].content).toBe("briefing content");
  });

  it("cleanup records the handle", async () => {
    const bt = createFakeBriefingTransport();
    await bt.cleanup("h1");
    expect(bt.cleanedUpHandles).toContain("h1");
  });
});

// ── FakeWorkflowState ─────────────────────────────────────────────────────────

describe("createFakeWorkflowState", () => {
  it("readTask returns empty object for unknown task", async () => {
    const ws = createFakeWorkflowState();
    const result = await ws.readTask("/ws", "feat", "T1");
    expect(result).toEqual({});
  });

  it("writeTask then readTask round-trips", async () => {
    const ws = createFakeWorkflowState();
    await ws.writeTask("/ws", "feat", "T1", { status: "in_progress" });
    const result = await ws.readTask("/ws", "feat", "T1");
    expect(result).toEqual({ status: "in_progress" });
  });

  it("appendLog accumulates entries in order", async () => {
    const ws = createFakeWorkflowState();
    await ws.appendLog("/ws", "feat", "T1", { action: "started" });
    await ws.appendLog("/ws", "feat", "T1", { action: "done" });
    const key = "/ws:feat:T1";
    expect(ws.logs.get(key)).toHaveLength(2);
    expect(ws.logs.get(key)![0]).toEqual({ action: "started" });
  });

  it("persistHandle stores the handle keyed by workspace+feature+task", async () => {
    const ws = createFakeWorkflowState();
    await ws.persistHandle("/ws", "feat", "T1", "handle-xyz");
    expect(ws.handles.get("/ws:feat:T1")).toBe("handle-xyz");
  });
});

// ── FakeCredentialPort ────────────────────────────────────────────────────────

describe("createFakeCredential", () => {
  it("returns default values", async () => {
    const cred = createFakeCredential();
    expect(await cred.getGitHubToken()).toBe("fake-github-token");
    expect(await cred.getSshPrivateKey()).toBe("");
  });

  it("returns overridden values", async () => {
    const pem = "[REDACTED:ssh-private-key]";
    const cred = createFakeCredential("my-token", pem);
    expect(await cred.getGitHubToken()).toBe("my-token");
    expect(await cred.getSshPrivateKey()).toBe(pem);
  });
});

// ── FakeWorkspacePull ─────────────────────────────────────────────────────────

describe("createFakeWorkspacePull", () => {
  it("records pull calls", async () => {
    const wp = createFakeWorkspacePull();
    await wp.pull("git@github.com:org/repo.git", "/tmp/ws", "main");
    expect(wp.pulls).toHaveLength(1);
    expect(wp.pulls[0]).toEqual({
      repoUrl: "git@github.com:org/repo.git",
      targetPath: "/tmp/ws",
      branch: "main",
    });
  });
});

// ── FakeEventEmitter ──────────────────────────────────────────────────────────

describe("createFakeEventEmitter", () => {
  it("records emitted events", () => {
    const emitter = createFakeEventEmitter();
    emitter.emit("task_claimed", { task_id: "T1" });
    emitter.emit("executor_spawn");
    expect(emitter.events).toHaveLength(2);
    expect(emitter.events[0].event).toBe("task_claimed");
    expect(emitter.events[0].data).toEqual({ task_id: "T1" });
    expect(emitter.events[1].event).toBe("executor_spawn");
  });
});

// ── FakeScheduler ─────────────────────────────────────────────────────────────

describe("createFakeScheduler", () => {
  it("records sleep durations without actually sleeping", async () => {
    const scheduler = createFakeScheduler();
    await scheduler.sleep(5000);
    await scheduler.sleep(2000);
    expect(scheduler.sleepCalls).toEqual([5000, 2000]);
  });
});

// ── FakeClock ─────────────────────────────────────────────────────────────────

describe("createFakeClock", () => {
  it("starts at the given initial time", () => {
    const clock = createFakeClock(1000);
    expect(clock.now()).toBe(1000);
  });

  it("nowIso returns a valid ISO string", () => {
    const clock = createFakeClock(0);
    expect(clock.nowIso()).toBe("1970-01-01T00:00:00.000Z");
  });

  it("sleep advances the clock", async () => {
    const clock = createFakeClock(0);
    await clock.sleep(3000);
    expect(clock.now()).toBe(3000);
  });

  it("advance increments the clock", () => {
    const clock = createFakeClock(100);
    clock.advance(50);
    expect(clock.now()).toBe(150);
  });

  it("setTime jumps to an absolute value", () => {
    const clock = createFakeClock(0);
    clock.setTime(99999);
    expect(clock.now()).toBe(99999);
  });
});

