73	/**
74	 * Materialize the implementation repo at taskRepoPath:
75	 *   - If path exists and origin matches URL: fetch + checkout + pull
76	 *   - Otherwise: clone fresh
77	 */
78	function materializeRepo(
79	  taskRepoUrl: string,
80	  taskRepoBranch: string,
81	  taskRepoPath: string,
82	  sshKeyPath: string | undefined,
83	): void {
84	  const env = buildGitEnv(sshKeyPath);
85	  const opts = { env, stdio: "pipe" as const };
86	
87	  if (existsSync(join(taskRepoPath, ".git"))) {
88	    let originUrl = "";
89	    try {
90	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
91	        ...opts, encoding: "utf-8",
92	      }).trim();
93	    } catch { /* no remote — fall through to clone */ }
94	
95	    if (originUrl === taskRepoUrl) {
96	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
97	      // Discard local changes from a previous session before checkout.
98	      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
99	      try {
100	        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
101	      } catch {
102	        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
103	      }
104	      try {
105	        execSync(
106	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
107	          opts,
108	        );
109	      } catch {
110	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
111	      }
112	      return;
113	    }
114	  }
115	
116	  // Clone fresh.
117	  mkdirSync(dirname(taskRepoPath), { recursive: true });
118	  if (existsSync(taskRepoPath)) {
119	    rmSync(taskRepoPath, { recursive: true, force: true });
120	  }
121	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
122	  try {
123	    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
124	  } catch {
125	    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
126	  }
127	}
