129	/**
130	 * Materialize the management repo at mgmtDir on the task branch.
131	 * Idempotent: if the dir already contains a valid clone of the same URL,
132	 * runs fetch + checkout -B <taskBranch> origin/<taskBranch> instead of a fresh clone.
133	 * Falls back to main if the task branch doesn't exist on origin yet.
134	 */
135	function materializeMgmtRepo(
136	  mgmtRepoUrl: string,
137	  mgmtDir: string,
138	  sshKeyPath: string | undefined,
139	  taskBranch: string,
140	): void {
141	  const env = buildGitEnv(sshKeyPath);
142	  const opts = { env, stdio: "pipe" as const };
143	
144	  const checkoutTaskBranch = (dir: string): void => {
145	    try {
146	      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
147	    } catch (taskBranchErr) {
148	      // Task branch not on origin yet — fall back to main.
149	      try {
150	        execSync(`git -C "${dir}" checkout main`, opts);
151	      } catch (mainCheckoutErr) {
152	        emit({ type: "mgmt_repo_checkout_failed", mgmt_dir: dir, branch: "main", details: String(mainCheckoutErr) });
153	      }
154	      try {
155	        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
156	      } catch {
157	        emit({ type: "mgmt_repo_pull_diverged", mgmt_dir: dir, note: "ff-only failed — using checked-out ref", task_branch_err: String(taskBranchErr) });
158	      }
159	    }
160	  };
161	
162	  if (existsSync(join(mgmtDir, ".git"))) {
163	    let originUrl = "";
164	    try {
165	      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
166	        ...opts, encoding: "utf-8",
167	      }).trim();
168	    } catch { /* no remote — fall through to clone */ }
169	
170	    if (originUrl === mgmtRepoUrl) {
171	      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
172	      checkoutTaskBranch(mgmtDir);
173	      return;
174	    }
175	  }
176	
177	  mkdirSync(dirname(mgmtDir), { recursive: true });
178	  if (existsSync(mgmtDir)) {
179	    rmSync(mgmtDir, { recursive: true, force: true });
180	  }
181	  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
182	  checkoutTaskBranch(mgmtDir);
183	}
