185	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
186	  { file: "yarn.lock",        tool: "yarn"    },
187	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
188	  { file: "bun.lockb",        tool: "bun"     },
189	  { file: "go.mod",           tool: "go"      },
190	  { file: "requirements.txt", tool: "python3" },
191	  { file: "pyproject.toml",   tool: "python3" },
192	  { file: "Cargo.toml",       tool: "cargo"   },
193	];
194	
195	function checkRequiredTools(taskRepoPath: string): string[] {
196	  const missing: string[] = [];
197	  const checked = new Set<string>();
198	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
199	    if (checked.has(tool)) continue;
200	    if (!existsSync(join(taskRepoPath, file))) continue;
201	    checked.add(tool);
202	    try {
203	      execSync(`which ${tool}`, { stdio: "pipe" });
204	    } catch {
205	      missing.push(tool);
206	    }
207	  }
208	  return missing;
209	}
