211	function copyWorkspaceClaude(workspaceRoot: string): void {
212	  const src = join(workspaceRoot, "CLAUDE.md");
213	  if (!existsSync(src)) return;
214	  const destDir = join(homedir(), ".claude");
215	  mkdirSync(destDir, { recursive: true });
216	  copyFileSync(src, join(destDir, "CLAUDE.md"));
217	}
218	
219	function copyDirRecursive(src: string, dest: string): void {
220	  mkdirSync(dest, { recursive: true });
221	  for (const entry of readdirSync(src)) {
222	    const srcPath = join(src, entry);
223	    const destPath = join(dest, entry);
224	    const stat = lstatSync(srcPath);
225	    if (stat.isDirectory()) {
226	      copyDirRecursive(srcPath, destPath);
227	    } else if (stat.isFile()) {
228	      copyFileSync(srcPath, destPath);
229	    }
230	  }
231	}
