233	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
234	  const globalSkillsDir = join(homedir(), ".claude", "skills");
235	  if (existsSync(globalSkillsDir)) {
236	    rmSync(globalSkillsDir, { recursive: true, force: true });
237	  }
238	  mkdirSync(globalSkillsDir, { recursive: true });
239	
240	  const copySkillsFrom = (sourceDir: string): void => {
241	    if (!existsSync(sourceDir)) return;
242	    let entries: string[];
243	    try { entries = readdirSync(sourceDir); } catch { return; }
244	    for (const entry of entries) {
245	      const srcPath = join(sourceDir, entry);
246	      try {
247	        const stat = lstatSync(srcPath);
248	        if (!stat.isDirectory()) continue;
249	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
250	      } catch (e) {
251	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
252	      }
253	    }
254	  };
255	
256	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
257	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
258	
259	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
260	  if (existsSync(wsSkillsDir)) {
261	    let entries: string[];
262	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
263	    for (const entry of entries) {
264	      if (entry === ".gitignore") continue;
265	      const srcPath = join(wsSkillsDir, entry);
266	      try {
267	        const stat = lstatSync(srcPath);
268	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
269	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
270	      } catch (e) {
271	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
272	      }
273	    }
274	  }
275	}
