284	async function main(): Promise<void> {
285	  // ── Read formal ABI env vars ────────────────────────────────────────────────
286	  let taskId: string;
287	  let featureId: string;
288	  let taskRepoUrl: string;
289	  let taskRepoBranch: string;
290	  let executorWorkdir: string;
291	  let mgmtRepoUrl: string;
292	  let briefingPath: string;
293	  let resultPath: string;
294	  let sshKeyPath: string | undefined;
295	  let githubToken: string;
296	
297	  try {
298	    taskId = requireEnv("TASK_ID");
299	    featureId = requireEnv("FEATURE_ID");
300	    taskRepoUrl = requireEnv("TASK_REPO_URL");
301	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
302	    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
303	    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
304	    briefingPath = requireEnv("BRIEFING_PATH");
305	    resultPath = requireEnv("RESULT_PATH");
306	    githubToken = process.env.GITHUB_TOKEN ?? "";
307	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
308	  } catch (e) {
309	    emit({ type: "executor_fatal", details: (e as Error).message });
310	    process.exit(1);
311	  }
312	
313	  const budgetTokensStr = process.env.BUDGET_TOKENS;
314	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
315	
316	  const implDir = join(executorWorkdir, "impl");
317	  const mgmtDir = join(executorWorkdir, "mgmt");
318	
319	  // Day-1 single-container extras.
320	  const workspaceRoot = mgmtDir;
321	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
322	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
323	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
324	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
325	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
326	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
327	  const mcpRagUrl = process.env.MCP_RAG_URL;
328	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
329	  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
330	  const implementationModel = process.env.IMPLEMENTATION_MODEL;
331	  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
332	  const implPrUrl = process.env.IMPL_PR_URL ?? "";
333	
334	  const runStartIso = new Date().toISOString();
335	
336	  // ── 1. Two-phase repo materialization ─────────────────────────────────────
337	  // Phase 1: management repo — checked out to the task branch so $WORKSPACE_ROOT
338	  // has the current task YAML (on the task branch, not main).
339	  try {
340	    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
341	    process.env.WORKSPACE_ROOT = mgmtDir;
342	  } catch (e) {
343	    const details = `mgmt repo materialization failed: ${String(e)}`;
344	    emit({ type: "executor_fatal", task_id: taskId, details });
345	    writeResult(resultPath, {
346	      terminal_status: "failed",
347	      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
348	    });
349	    process.exit(0);
350	  }
351	
352	  // Phase 2: implementation repo
353	  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
354	  try {
355	    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
356	    process.env.TASK_REPO_PATH = implDir;
357	  } catch (e) {
358	    const details = `impl repo materialization failed: ${String(e)}`;
359	    emit({ type: "executor_fatal", task_id: taskId, details });
360	    writeResult(resultPath, {
361	      terminal_status: "failed",
362	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
363	    });
364	    process.exit(0);
365	  }
366	
367	  // Ensure `feature/{featureId}` exists on the impl repo remote so PR creation
368	  // can target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base branch, e.g.
369	  // "main") as the push source — not TASK_BASE_BRANCH, which is the feature branch
370	  // itself and cannot be used as its own creation source.
371	  if (taskRepoBaseBranch) {
372	    ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
373	  }
374	
375	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
376	  const missingTools = checkRequiredTools(implDir);
377	  if (missingTools.length > 0) {
378	    const details = `missing tools: ${missingTools.join(", ")}`;
379	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
380	    writeResult(resultPath, {
381	      terminal_status: "blocked",
382	      blocked_reason: "missing_tool",
383	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
384	    });
385	    process.exit(0);
386	  }
387	
388	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
389	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
390	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
391	  if (workflowLocalPath) setupGlobalSettings(workflowLocalPath, emit);
392	
393	  // ── 4. Read briefing ────────────────────────────────────────────────────────
394	  let briefingContent: string;
395	  try {
396	    briefingContent = readFileSync(briefingPath, "utf-8");
397	  } catch (e) {
398	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
399	    writeResult(resultPath, {
400	      terminal_status: "failed",
401	      blocked_reason: `briefing_read_failed: ${String(e)}`,
402	    });
403	    process.exit(0);
404	  }
405	
406	  // Append hard-stop rule for missing tools.
407	  const effectiveBriefing =
408	    briefingContent +
409	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
410	
411	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
412	  const mcpArgs: string[] = [];
413	  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
414	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
415	    if (mcpRagUrl) {
416	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
417	    }
418	    if (gitnexusMcpUrl) {
419	      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
420	    }
421	    if (figmaToken) {
422	      mcpConfig.mcpServers["figma"] = {
423	        type: "stdio",
424	        command: "npx",
425	        args: ["-y", "@figma/mcp-server"],
426	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
427	      };
428	    }
429	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
430	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
431	    mcpArgs.push("--mcp-config", mcpConfigPath);
432	  }
433	
434	  if (mcpRagUrl) {
435	    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
436	  } else {
437	    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
438	  }
439	
440	  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
441	  // PYTHONUSERBASE redirects all `pip install --user` into the executor's own
442	  // directory, preventing cross-executor pip registration conflicts when two
443	  // executors work on the same Python repo concurrently (e.g. T2 then T4 on cycle).
444	  const pybase = join(executorWorkdir, "pybase");
445	  const claudeEnv = {
446	    ...buildGitEnv(sshKeyPath),
447	    CLAUDE_AGENT_RUNTIME: "1",
448	    RESULT_PATH: resultPath,
449	    GITHUB_TOKEN: githubToken,
450	    TASK_REPO_PATH: implDir,
451	    PYTHONUSERBASE: pybase,
452	    PATH: `${join(pybase, "bin")}:${process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin"}`,
453	  };
454	
455	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
456	
457	  let spawnResult: SpawnResult | undefined;
458	  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
459	  let logFlushed = false;
460	
461	  try {
462	    spawnResult = await new Promise<SpawnResult>((resolve) => {
463	      const stdoutChunks: string[] = [];
464	
465	      const child = spawn(
466	        "claude",
467	        [
468	          "-p", effectiveBriefing,
469	          "--max-turns", String(maxTurns),
470	          "--output-format", "stream-json",
471	          "--verbose",
472	          "--dangerously-skip-permissions",
473	          ...(implementationModel ? ["--model", implementationModel] : []),
474	          ...mcpArgs,
475	        ],
476	        { cwd: implDir, env: claudeEnv },
477	      );
478	
479	      child.stdout.setEncoding("utf-8");
480	      child.stderr.setEncoding("utf-8");
481	
482	      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
483	      let stdoutLineBuf = "";
484	      child.stdout.on("data", (chunk: string) => {
485	        stdoutChunks.push(chunk);
486	        process.stdout.write(chunk);
487	        if (resultWatchdog === null) {
488	          stdoutLineBuf += chunk;
489	          const lines = stdoutLineBuf.split("\n");
490	          stdoutLineBuf = lines.pop() ?? "";
491	          for (const line of lines) {
492	            if (line.includes('"type":"result"')) {
493	              resultWatchdog = setTimeout(() => {
494	                if (!child.killed) child.kill("SIGTERM");
495	              }, 30_000);
496	              break;
497	            }
498	          }
499	        }
500	      });
501	
502	      child.stderr.on("data", (chunk: string) => {
503	        process.stderr.write(chunk);
504	      });
505	
506	      child.on("error", (err: Error) => {
507	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
508	        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
509	      });
510	
511	      child.on("exit", () => {
512	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
513	        setTimeout(() => {
514	          if (!child.stdout.destroyed) child.stdout.destroy();
515	          if (!child.stderr.destroyed) child.stderr.destroy();
516	        }, 0);
517	      });
518	
519	      child.on("close", (code: number | null, signal: string | null) => {
520	        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
521	      });
522	    });
523	
524	    emit({
525	      type: "claude_exit",
526	      task_id: taskId,
527	      feature_id: featureId,
528	      exit_code: spawnResult.status,
529	      signal: spawnResult.signal ?? null,
530	    });
531	
532	    // ── 7. Token audit ────────────────────────────────────────────────────────
533	    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;
534	
535	    if (tokenUsage === undefined) {
536	      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
537	    } else {
538	      if (tokenUsage.pricingFallback) {
539	        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
540	      }
541	      emit({
542	        type: "budget_audit",
543	        task_id: taskId,
544	        feature_id: featureId,
545	        total_tokens: tokenUsage.input + tokenUsage.output,
546	        max_tokens: budgetTokens,
547	      });
548	    }
549	
550	    // ── 7a. RAG query audit
551	    if (spawnResult.stdout) {
552	      for (const rq of extractRagQueries(spawnResult.stdout)) {
553	        emit({ type: "rag_query", ...rq });
554	      }
555	    }
556	
557	    // ── 7b. GitNexus query audit
558	    if (spawnResult.stdout) {
559	      for (const gq of extractGitNexusQueries(spawnResult.stdout)) {
560	        emit({ type: "gitnexus_query", ...gq });
561	      }
562	    }
563	
564	    // ── 8. Check for result.json written by Claude ────────────────────────────
565	    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
566	    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
567	    // when Claude exits cleanly without writing result.json — both paths previously
568	    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
569	    // echoed via a Read of T<n>.yaml) were captured as the impl PR.
570	
571	    if (existsSync(resultPath)) {
572	      let raw: unknown;
573	      try {
574	        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
575	      } catch {
576	        raw = null;
577	      }
578	      if (isValidResult(raw)) {
579	        let claudeResult = raw as ExecutorResult;
580	        if (tokenUsage !== undefined && !claudeResult.token_usage) {
581	          claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
582	        }
583	        if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
584	          claudeResult.cost_usd = tokenUsage.cost_usd;
585	        }
586	
587	        // Refuse terminal_status: in_review without a valid pr_url. Checks:
588	        //   1. pr_url must be present and non-empty.
589	        //   2. pr_url owner/repo must match the task's implementation repo.
590	        //   3. PR head branch must be feature/{featureId}-{taskId} (API-verified).
591	        // This closes the bug where a PR from a different feature/repo appeared
592	        // in Claude's stdout and was captured as the impl PR.
593	        let prUrlCtx: Parameters<typeof enforceInReviewRequiresPrUrl>[1];
594	        try {
595	          const { owner, repo } = parseGitHubCoords(taskRepoUrl);
596	          prUrlCtx = { expectedOwner: owner, expectedRepo: repo, featureId, taskId, githubToken: githubToken || undefined };
597	        } catch {
598	          // If taskRepoUrl can't be parsed, skip repo/branch checks.
599	          prUrlCtx = undefined;
600	        }
601	        const enforced = enforceInReviewRequiresPrUrl(claudeResult, prUrlCtx);
602	        if (enforced.rewritten) {
603	          emit({
604	            type: "in_review_refused_no_pr_url",
605	            task_id: taskId,
606	            feature_id: featureId,
607	            blocked_reason: enforced.result.blocked_reason,
608	          });
609	        }
610	        claudeResult = enforced.result;
611	
612	        if (
613	          budgetTokens !== undefined &&
614	          tokenUsage !== undefined &&
615	          tokenUsage.input + tokenUsage.output > budgetTokens
616	        ) {
617	          writeResult(resultPath, {
618	            terminal_status: "blocked",
619	            blocked_reason: "budget_exceeded",
620	            token_usage: tokenUsage,
621	          });
622	        } else {
623	          writeResult(resultPath, claudeResult);
624	        }
625	
626	        if (logSinkEnabled && workspaceRoot && taskBranch) {
627	          flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath, emit);
628	          logFlushed = true;
629	        }
630	
631	        // Return normally — Layer 1 recovery (finally block below) will no-op
632	        // because a valid result.json now exists.
633	        return;
634	      }
635	    }
636	
637	    // ── 9. Claude did not write result.json ──────────────────────────────────
638	    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
639	    if (
640	      budgetTokens !== undefined &&
641	      tokenUsage !== undefined &&
642	      tokenUsage.input + tokenUsage.output > budgetTokens
643	    ) {
644	      writeResult(resultPath, {
645	        terminal_status: "blocked",
646	        blocked_reason: "budget_exceeded",
647	        token_usage: tokenUsage,
648	      });
649	      if (logSinkEnabled && workspaceRoot && taskBranch) {
650	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath, emit);
651	        logFlushed = true;
652	      }
653	      return;
654	    }
655	
656	    // No result.json produced — recovery will write one in the finally block.
657	
658	  } finally {
659	    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
660	    // Runs regardless of how the spawn ended. No-op when result.json has a
661	    // valid in_review result (Claude finished cleanly). Otherwise: commits
662	    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
663	    // writes a blocked result.json.
664	    await runRecovery({
665	      spawnResult,
666	      taskId,
667	      featureId,
668	      taskRepoBranch,
669	      taskRepoPath: implDir,
670	      taskRepoUrl,
671	      githubToken,
672	      sshKeyPath,
673	      gitAuthorEmail,
674	      gitAuthorName,
675	      resultPath,
676	      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
677	      kind: executorKind,
678	      implPrUrl: implPrUrl || undefined,
679	    });
680	
681	    // Flush log after recovery (best-effort, uses result.json to determine outcome).
682	    // Skip if already flushed in the success or budget-exceeded paths above.
683	    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
684	      let outcome = "unknown";
685	      try {
686	        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
687	        outcome = raw.terminal_status;
688	      } catch { /* ignore */ }
689	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath, emit);
690	    }
691	  }
692	}
693	
694	
695	main().catch((e) => {
696	  try {
697	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
698	  } catch { /* last resort */ }
699	  process.exit(1);
700	});
