/**
 * ABI contract between the orchestrator and any executor.
 *
 * The orchestrator serialises ExecutorInput into env vars before spawning
 * the executor process. The executor writes an ExecutorResult to the path
 * at resultPath. The orchestrator reads and validates that file on exit.
 */

// ── Handle / completion types (Wave 1 — ports-and-adapters foundation) ───────

/** Opaque identifier for a single in-flight executor run. */
export type ExecutorHandle = string;

/** Discriminates claim work from review-fix work in the reap loop. */
export type HandleKind = "impl" | "review-fix" | "review" | "rebase";

/** Sub-discriminator for review-fix handles. */
export type HandleSubkind = "rebase" | "respond";

/**
 * Metadata registered with the broker at submit time.
 * Carried on every completion so any orchestrator can dispatch without
 * needing prior knowledge of the submit — opportunistic dispatch.
 */
export interface HandleMetadata {
  kind: HandleKind;
  subkind?: HandleSubkind;
  task_id: string;
  feature_id: string;
  tenant_id?: string;
  started_at: string; // ISO 8601
}

/**
 * One item returned by CompletionBrokerPort.listCompleted (peek-and-lock).
 * locked_until is present when the broker has marked the item locked.
 */
export interface ExecutorCompletion {
  handle: ExecutorHandle;
  result: ExecutorResult;
  metadata: HandleMetadata;
  locked_until?: number; // unix ms timestamp
}

/**
 * Extended input for ExecutorPort.submit.
 * Adds the callback URL and per-handle nonce that the runner wrapper uses
 * to POST its result back to the completion broker.
 */
export interface ExecutorPortInput extends ExecutorInput {
  /** The URL the runner wrapper will POST { handle, nonce, result } to. */
  callbackUrl: string;
  /** Single-use token; validated by the broker on POST; invalidated on ack. */
  nonce: string;
  /**
   * Override the handle kind registered with the broker. When absent the
   * adapter falls back to its constructor-level handleKind (defaulting to "impl").
   */
  kind?: HandleKind;
}

/** HTTP POST body the runner wrapper sends to the broker on completion. */
export interface RunnerCallbackPayload {
  handle: ExecutorHandle;
  nonce: string;
  result: ExecutorResult;
}

// ── Original ABI types (kept for backward compatibility) ─────────────────────

export interface ExecutorInput {
  taskId: string;
  featureId: string;
  workspaceId: string;
  /** Executor invocation UUID. Passed as `HANDLE` env var; formalises existing docker usage. */
  handle: string;
  /** Git URL of the implementation repo (SSH or HTTPS). */
  taskRepoUrl: string;
  /** Feature branch the executor must check out and push to. */
  taskRepoBranch: string;
  /**
   * Branch that implementation PRs must target. Set by the orchestrator to the
   * feature branch (e.g. `feature/{featureId}`) so task PRs collect there before
   * the Handoff Trigger merges the feature branch into the repo's base branch.
   * Executors read this as `TASK_BASE_BRANCH` and pass it as the `base` field
   * when calling `pr-create`.
   */
  taskBaseBranch: string;
  /**
   * The impl repo's root base branch from workspace.yaml (e.g. `main`).
   * Used by the executor to create `feature/{featureId}` on the impl repo remote
   * when it does not yet exist. Distinct from `taskBaseBranch`, which is the PR
   * target (the feature branch itself) and must not be used as a push source.
   * Executors read this as `TASK_REPO_BASE_BRANCH`.
   */
  taskRepoBaseBranch?: string;
  /**
   * Per-handle base directory. The executor derives:
   *   - `${executorWorkdir}/impl` — implementation repo (replaces `taskRepoPath`)
   *   - `${executorWorkdir}/mgmt` — management repo clone (derives `WORKSPACE_ROOT`)
   */
  executorWorkdir: string;
  /** Git URL of the management (workspace) repo — cloned read-only by the executor. */
  mgmtRepoUrl: string;
  /** Path the executor must write result.json to. */
  resultPath: string;
  /** Optional token budget; absent for non-LLM executors. */
  budgetTokens?: number;
  /** Model ID to use for the LLM; resolved from workspace model_policy. */
  implementationModel?: string;
  sshPrivateKey: string;
  githubToken: string;
}

export type TerminalStatus = "in_review" | "blocked" | "failed";

export interface ExecutorResult {
  terminal_status: TerminalStatus;
  token_usage?: { input: number; output: number; model?: string };
  /** Required when terminal_status === "blocked". */
  blocked_reason?: string;
  /** Required when terminal_status === "blocked". */
  blocked_suggestion?: string;
  /**
   * URL of the implementation-repo pull request opened by the executor.
   * Populated whenever the executor opened a PR — independent of terminal_status.
   * A blocked task with a draft PR still reports pr_url so the failed attempt is
   * documented. Absent when no commits were pushed (no PR to open).
   */
  pr_url?: string;
  /**
   * Path to a handover.md file written by the executor or the post-hoc recovery
   * routine (Layer 1). Optional — present only when a handover exists.
   * The orchestrator reads this on re-claim and prepends its contents to the next
   * agent's briefing under a "## Continuing previous run" heading (Layer 3).
   */
  cost_usd?: number;
  handover_path?: string;
}

/** Terminal status values produced by the reviewer executor (kind=review). */
export type ReviewerTerminalStatus = "passed" | "change_requested" | "escalate";

/**
 * Result written by the reviewer executor to result.json.
 * Routed to dispatchReviewResult in the reap loop — separate from ExecutorResult.
 */
export interface ReviewerResult {
  terminal_status: ReviewerTerminalStatus;
  verdict: ReviewerTerminalStatus;
  confidence: number;
  notes: string;
  review_url?: string;
  /** Set to true when the review POST was skipped due to HTTP 422 (self-review restriction). */
  self_review_skipped?: boolean;
}

/**
 * The orchestrator-side seam every executor must satisfy.
 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
 */
export interface ExecutorAdapter {
  run(input: ExecutorInput): Promise<ExecutorResult>;
}

