1	/**
2	 * Fake adapters for every port defined in ports.ts.
3	 *
4	 * These are no-I/O, in-memory implementations used in hermetic
5	 * orchestrator-core tests. Each fake records calls so tests can
6	 * assert on what the core invoked without side effects.
7	 */
8	
9	import type {
10	  ExecutorPort,
11	  WorkflowStatePort,
12	  CredentialPort,
13	  WorkspacePullPort,
14	  EventEmitterPort,
15	  SchedulerPort,
16	  ClockPort,
17	} from "./ports.js";
18	import type {
19	  ExecutorHandle,
20	  ExecutorPortInput,
21	  ExecutorResult,
22	} from "./types.js";
23	
24	// ── FakeExecutorPort ──────────────────────────────────────────────────────────
25	
26	export interface FakeExecutorPortOpts {
27	  /** Override submit; default generates a deterministic handle from taskId. */
28	  submit?: (input: ExecutorPortInput) => Promise<ExecutorHandle>;
29	  /** Override readResult; default returns { terminal_status: "in_review" }. */
30	  readResult?: (handle: ExecutorHandle) => Promise<ExecutorResult>;
31	}
32	
33	export interface FakeExecutorPort extends ExecutorPort {
34	  /** Handles returned by every submit call, in order. */
35	  readonly submittedHandles: ExecutorHandle[];
36	  /** Inputs received by every submit call, in order. */
37	  readonly submittedInputs: ExecutorPortInput[];
38	}
39	
40	export function createFakeExecutorPort(
41	  opts?: FakeExecutorPortOpts,
42	): FakeExecutorPort {
43	  const submittedHandles: ExecutorHandle[] = [];
44	  const submittedInputs: ExecutorPortInput[] = [];
45	
46	  return {
47	    submittedHandles,
48	    submittedInputs,
49	
50	    async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
51	      if (opts?.submit) {
52	        const h = await opts.submit(input);
53	        submittedHandles.push(h);
54	        submittedInputs.push(input);
55	        return h;
56	      }
57	      const h: ExecutorHandle = `fake-handle-${input.taskId}-${submittedHandles.length}`;
58	      submittedHandles.push(h);
59	      submittedInputs.push(input);
60	      return h;
61	    },
62	
63	    async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
64	      if (opts?.readResult) return opts.readResult(_handle);
65	      return { terminal_status: "in_review" };
66	    },
67	  };
68	}
69	
70	
71	// ── FakeWorkflowStatePort ─────────────────────────────────────────────────────
72	
73	export interface FakeWorkflowState extends WorkflowStatePort {
74	  readonly tasks: Map<string, Record<string, unknown>>;
75	  readonly logs: Map<string, Record<string, unknown>[]>;
76	  readonly handles: Map<string, ExecutorHandle>;
77	}
78	
79	export function createFakeWorkflowState(): FakeWorkflowState {
80	  const tasks = new Map<string, Record<string, unknown>>();
81	  const logs = new Map<string, Record<string, unknown>[]>();
82	  const handles = new Map<string, ExecutorHandle>();
83	
84	  function key(
85	    workspaceRoot: string,
86	    featureId: string,
87	    taskId: string,
88	  ): string {
89	    return `${workspaceRoot}:${featureId}:${taskId}`;
90	  }
91	
92	  return {
93	    tasks,
94	    logs,
95	    handles,
96	
97	    async readTask(
98	      workspaceRoot: string,
99	      featureId: string,
