/**
 * Fake adapters for every port defined in ports.ts.
 *
 * These are no-I/O, in-memory implementations used in hermetic
 * orchestrator-core tests. Each fake records calls so tests can
 * assert on what the core invoked without side effects.
 */

import type {
  ExecutorPort,
  WorkflowStatePort,
  CredentialPort,
  WorkspacePullPort,
  EventEmitterPort,
  SchedulerPort,
  ClockPort,
} from "./ports.js";
import type {
  ExecutorHandle,
  ExecutorPortInput,
  ExecutorResult,
} from "./types.js";

// ── FakeExecutorPort ──────────────────────────────────────────────────────────

export interface FakeExecutorPortOpts {
  /** Override submit; default generates a deterministic handle from taskId. */
  submit?: (input: ExecutorPortInput) => Promise<ExecutorHandle>;
  /** Override readResult; default returns { terminal_status: "in_review" }. */
  readResult?: (handle: ExecutorHandle) => Promise<ExecutorResult>;
}

export interface FakeExecutorPort extends ExecutorPort {
  /** Handles returned by every submit call, in order. */
  readonly submittedHandles: ExecutorHandle[];
  /** Inputs received by every submit call, in order. */
  readonly submittedInputs: ExecutorPortInput[];
}

export function createFakeExecutorPort(
  opts?: FakeExecutorPortOpts,
): FakeExecutorPort {
  const submittedHandles: ExecutorHandle[] = [];
  const submittedInputs: ExecutorPortInput[] = [];

  return {
    submittedHandles,
    submittedInputs,

    async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
      if (opts?.submit) {
        const h = await opts.submit(input);
        submittedHandles.push(h);
        submittedInputs.push(input);
        return h;
      }
      const h: ExecutorHandle = `fake-handle-${input.taskId}-${submittedHandles.length}`;
      submittedHandles.push(h);
      submittedInputs.push(input);
      return h;
    },

    async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
      if (opts?.readResult) return opts.readResult(_handle);
      return { terminal_status: "in_review" };
    },
  };
}


// ── FakeWorkflowStatePort ─────────────────────────────────────────────────────

export interface FakeWorkflowState extends WorkflowStatePort {
  readonly tasks: Map<string, Record<string, unknown>>;
  readonly logs: Map<string, Record<string, unknown>[]>;
  readonly handles: Map<string, ExecutorHandle>;
}

export function createFakeWorkflowState(): FakeWorkflowState {
  const tasks = new Map<string, Record<string, unknown>>();
  const logs = new Map<string, Record<string, unknown>[]>();
  const handles = new Map<string, ExecutorHandle>();

  function key(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
  ): string {
    return `${workspaceRoot}:${featureId}:${taskId}`;
  }

  return {
    tasks,
    logs,
    handles,

    async readTask(
      workspaceRoot: string,
      featureId: string,
      taskId: string,
    ): Promise<Record<string, unknown>> {
      return tasks.get(key(workspaceRoot, featureId, taskId)) ?? {};
    },

    async writeTask(
      workspaceRoot: string,
      featureId: string,
      taskId: string,
      data: Record<string, unknown>,
    ): Promise<void> {
      tasks.set(key(workspaceRoot, featureId, taskId), data);
    },

    async appendLog(
      workspaceRoot: string,
      featureId: string,
      taskId: string,
      entry: Record<string, unknown>,
    ): Promise<void> {
      const k = key(workspaceRoot, featureId, taskId);
      const existing = logs.get(k) ?? [];
      existing.push(entry);
      logs.set(k, existing);
    },

    async persistHandle(
      workspaceRoot: string,
      featureId: string,
      taskId: string,
      handle: ExecutorHandle,
    ): Promise<void> {
      handles.set(key(workspaceRoot, featureId, taskId), handle);
    },
  };
}

// ── FakeCredentialPort ────────────────────────────────────────────────────────

export function createFakeCredential(
  githubToken = "fake-github-token",
  sshPrivateKey = "",
): CredentialPort {
  return {
    async getGitHubToken(_tenantId?: string): Promise<string> {
      return githubToken;
    },
    async getSshPrivateKey(_tenantId?: string): Promise<string> {
      return sshPrivateKey;
    },
  };
}

// ── FakeWorkspacePullPort ─────────────────────────────────────────────────────

export interface FakeWorkspacePull extends WorkspacePullPort {
  readonly pulls: { repoUrl: string; targetPath: string; branch: string }[];
}

export function createFakeWorkspacePull(): FakeWorkspacePull {
  const pulls: { repoUrl: string; targetPath: string; branch: string }[] = [];

  return {
    pulls,
    async pull(
      repoUrl: string,
      targetPath: string,
      branch: string,
    ): Promise<void> {
      pulls.push({ repoUrl, targetPath, branch });
    },
  };
}

// ── FakeEventEmitterPort ──────────────────────────────────────────────────────

export interface FakeEventEmitter extends EventEmitterPort {
  readonly events: { event: string; data?: Record<string, unknown> }[];
}

export function createFakeEventEmitter(): FakeEventEmitter {
  const events: { event: string; data?: Record<string, unknown> }[] = [];

  return {
    events,
    emit(event: string, data?: Record<string, unknown>): void {
      events.push({ event, data });
    },
  };
}

// ── FakeSchedulerPort ─────────────────────────────────────────────────────────

export interface FakeScheduler extends SchedulerPort {
  /** Recorded sleep durations in order. */
  readonly sleepCalls: number[];
}

export function createFakeScheduler(): FakeScheduler {
  const sleepCalls: number[] = [];

  return {
    sleepCalls,
    async sleep(ms: number): Promise<void> {
      sleepCalls.push(ms);
    },
  };
}

// ── FakeClockPort ─────────────────────────────────────────────────────────────

export interface FakeClock extends ClockPort {
  /** Advance the clock by ms milliseconds. */
  advance(ms: number): void;
  /** Jump the clock to an absolute unix-ms timestamp. */
  setTime(ms: number): void;
}

export function createFakeClock(initialTimeMs = 0): FakeClock {
  let currentTime = initialTimeMs;

  return {
    now(): number {
      return currentTime;
    },

    nowIso(): string {
      return new Date(currentTime).toISOString();
    },

    async sleep(ms: number): Promise<void> {
      currentTime += ms;
    },

    advance(ms: number): void {
      currentTime += ms;
    },

    setTime(ms: number): void {
      currentTime = ms;
    },
  };
}

