import type { TaskNotifierPort, TaskNotificationEvent } from "../src/ports/task-notifier.port.js";

function makeNotifier(): { notifier: TaskNotifierPort; events: TaskNotificationEvent[]; error?: Error } {
  const events: TaskNotificationEvent[] = [];
  const notifier: TaskNotifierPort = { notify: async (e) => { events.push(e); } };
  return { notifier, events };
}

