1	/**
2	 * Enforce invariants on terminal_status="in_review" results:
3	 *   1. pr_url must be present and non-empty.
4	 *   2. (when ctx provided) pr_url must point to the expected owner/repo.
5	 *   3. (when ctx + githubToken provided) PR head branch must be
6	 *      "feature/{featureId}-{taskId}" — verified via GitHub API.
7	 *
8	 * Background. The pre-fix executor scraped GitHub PR URLs from claude's stdout
9	 * with a regex and used the first match as the impl PR url. That regex matched
10	 * any PR URL on the stream — including the workspace claim PR url echoed back
11	 * via a Read of T<n>.yaml during agent work. When the agent skipped pr-create
12	 * after pr-self-review, the workspace claim PR was silently captured as the
13	 * impl PR.
14	 *
15	 * The second class of bug: an agent from a different feature (or task) had
16	 * already opened a PR; the wrong PR URL appeared in stdout and was captured.
17	 * Checks 2 + 3 close that gap by verifying owner/repo + head branch.
18	 */
19	
20	import { spawnSync } from "node:child_process";
21	import type { ExecutorResult } from "@workflow/runtime-abi";
22	
23	// ── Constants ─────────────────────────────────────────────────────────────────
24	
25	const REWRITE_BLOCKED_REASON = "pr_url_missing";
26	const REWRITE_BLOCKED_SUGGESTION =
27	  "Executor reported terminal_status=in_review but result.json had no pr_url. " +
28	  "The pr-create skill was likely never invoked (or it failed silently). " +
29	  "Manually invoke /pr-create against the task branch in the impl repo, fill " +
30	  "result.pr_url with the resulting URL, and re-resume the task.";
31	
32	// ── Types ─────────────────────────────────────────────────────────────────────
33	
34	export interface EnforceResult {
35	  result: ExecutorResult;
36	  rewritten: boolean;
37	}
38	
39	/**
40	 * Optional context for deeper pr_url validation.
41	 * When provided, the enforcer checks owner/repo and (with a token) head branch.
42	 */
43	export interface PrUrlCtx {
44	  /** Expected repo owner derived from taskRepoUrl, e.g. "BroTraders". */
45	  expectedOwner: string;
46	  /** Expected repo name derived from taskRepoUrl, e.g. "cycle". */
47	  expectedRepo: string;
48	  /** Feature ID, e.g. "cycle-gateio-integration". */
49	  featureId: string;
50	  /** Task ID, e.g. "T2". */
51	  taskId: string;
52	  /** GitHub token for API calls — branch check is skipped when absent. */
53	  githubToken?: string;
54	}
55	
56	// ── Helpers ───────────────────────────────────────────────────────────────────
57	
58	interface PrCoords {
59	  owner: string;
60	  repo: string;
61	  number: string;
62	}
63	
64	/** Parse a GitHub PR URL into { owner, repo, number }. Returns null if not parseable. */
65	export function parsePrUrl(url: string): PrCoords | null {
66	  const m = /https?:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(url);
67	  if (!m) return null;
68	  return { owner: m[1], repo: m[2], number: m[3] };
69	}
70	
71	/**
72	 * Fetch the head branch of a GitHub PR via the REST API.
73	 * Returns the branch name, or null if the call fails for any reason.
74	 * Synchronous (uses spawnSync) to keep the enforcer pure-synchronous.
75	 */
76	export function fetchPrHeadBranch(
77	  owner: string,
78	  repo: string,
79	  number: string,
80	  token: string,
81	): string | null {
82	  const result = spawnSync(
83	    "curl",
84	    [
85	      "-s",
86	      "-H", "Accept: application/vnd.github+json",
87	      "-H", `Authorization: Bearer ${token}`,
88	      "-H", "X-GitHub-Api-Version: 2022-11-28",
89	      `https://api.github.com/repos/${owner}/${repo}/pulls/${number}`,
90	    ],
91	    { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
92	  );
93	  if (result.error || !result.stdout?.trim()) return null;
94	  try {
95	    const pr = JSON.parse(result.stdout) as { head?: { ref?: string } };
96	    return pr.head?.ref ?? null;
97	  } catch {
98	    return null;
99	  }
100	}
101	
102	// ── Main export ───────────────────────────────────────────────────────────────
103	
104	/**
105	 * Enforce pr_url correctness on in_review results.
106	 *
107	 * Check order:
108	 *   1. pr_url must be present and non-empty → blocked(pr_url_missing)
109	 *   2. (ctx) pr_url must parse as a valid GitHub PR URL → blocked(pr_url_unparseable)
110	 *   3. (ctx) owner/repo must match expectedOwner/expectedRepo → blocked(pr_url_wrong_repo)
111	 *   4. (ctx + githubToken) head branch must be feature/{featureId}-{taskId}
112	 *      → blocked(pr_url_wrong_branch). Skipped on API error (fail-open).
113	 *
114	 * Pure: does not mutate the input.
115	 */
116	export function enforceInReviewRequiresPrUrl(
117	  result: ExecutorResult,
118	  ctx?: PrUrlCtx,
119	): EnforceResult {
120	  if (result.terminal_status !== "in_review") {
121	    return { result, rewritten: false };
122	  }
123	
124	  const rawUrl = result.pr_url?.trim() ?? "";
125	
126	  // Check 1: URL must be present.
127	  if (!rawUrl) {
128	    return {
129	      result: {
130	        ...result,
131	        terminal_status: "blocked",
132	        blocked_reason: REWRITE_BLOCKED_REASON,
133	        blocked_suggestion: REWRITE_BLOCKED_SUGGESTION,
134	        pr_url: undefined,
135	      },
136	      rewritten: true,
137	    };
138	  }
139	
140	  // Checks 2-4 require context.
141	  if (!ctx) {
142	    return { result, rewritten: false };
143	  }
144	
145	  // Check 2: URL must parse as a GitHub PR URL.
146	  const coords = parsePrUrl(rawUrl);
147	  if (!coords) {
148	    return {
149	      result: {
150	        ...result,
151	        terminal_status: "blocked",
152	        blocked_reason: "pr_url_unparseable",
153	        blocked_suggestion:
154	          `pr_url "${rawUrl}" is not a valid GitHub PR URL. ` +
155	          "Expected format: https://github.com/{owner}/{repo}/pull/{n}. " +
156	          "Ensure pr-create was invoked and wrote a valid PR URL to result.json.",
157	        pr_url: undefined,
158	      },
159	      rewritten: true,
160	    };
161	  }
162	
163	  // Check 3: owner/repo must match the task's implementation repo.
164	  const ownerMatch = coords.owner.toLowerCase() === ctx.expectedOwner.toLowerCase();
165	  const repoMatch = coords.repo.toLowerCase() === ctx.expectedRepo.toLowerCase();
166	  if (!ownerMatch || !repoMatch) {
167	    return {
168	      result: {
169	        ...result,
170	        terminal_status: "blocked",
171	        blocked_reason: "pr_url_wrong_repo",
172	        blocked_suggestion:
173	          `pr_url points to ${coords.owner}/${coords.repo} but the task targets ` +
174	          `${ctx.expectedOwner}/${ctx.expectedRepo}. ` +
175	          "Ensure pr-create was run against the correct implementation repo and " +
176	          "wrote the resulting URL to result.json.",
177	        pr_url: undefined,
178	      },
179	      rewritten: true,
180	    };
