/**
 * Enforce invariants on terminal_status="in_review" results:
 *   1. pr_url must be present and non-empty.
 *   2. (when ctx provided) pr_url must point to the expected owner/repo.
 *   3. (when ctx + githubToken provided) PR head branch must be
 *      "feature/{featureId}-{taskId}" — verified via GitHub API.
 *
 * Background. The pre-fix executor scraped GitHub PR URLs from claude's stdout
 * with a regex and used the first match as the impl PR url. That regex matched
 * any PR URL on the stream — including the workspace claim PR url echoed back
 * via a Read of T<n>.yaml during agent work. When the agent skipped pr-create
 * after pr-self-review, the workspace claim PR was silently captured as the
 * impl PR.
 *
 * The second class of bug: an agent from a different feature (or task) had
 * already opened a PR; the wrong PR URL appeared in stdout and was captured.
 * Checks 2 + 3 close that gap by verifying owner/repo + head branch.
 */

import { spawnSync } from "node:child_process";
import type { ExecutorResult } from "@workflow/runtime-abi";

// ── Constants ─────────────────────────────────────────────────────────────────

const REWRITE_BLOCKED_REASON = "pr_url_missing";
const REWRITE_BLOCKED_SUGGESTION =
  "Executor reported terminal_status=in_review but result.json had no pr_url. " +
  "The pr-create skill was likely never invoked (or it failed silently). " +
  "Manually invoke /pr-create against the task branch in the impl repo, fill " +
  "result.pr_url with the resulting URL, and re-resume the task.";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface EnforceResult {
  result: ExecutorResult;
  rewritten: boolean;
}

/**
 * Optional context for deeper pr_url validation.
 * When provided, the enforcer checks owner/repo and (with a token) head branch.
 */
export interface PrUrlCtx {
  /** Expected repo owner derived from taskRepoUrl, e.g. "BroTraders". */
  expectedOwner: string;
  /** Expected repo name derived from taskRepoUrl, e.g. "cycle". */
  expectedRepo: string;
  /** Feature ID, e.g. "cycle-gateio-integration". */
  featureId: string;
  /** Task ID, e.g. "T2". */
  taskId: string;
  /** GitHub token for API calls — branch check is skipped when absent. */
  githubToken?: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

interface PrCoords {
  owner: string;
  repo: string;
  number: string;
}

/** Parse a GitHub PR URL into { owner, repo, number }. Returns null if not parseable. */
export function parsePrUrl(url: string): PrCoords | null {
  const m = /https?:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(url);
  if (!m) return null;
  return { owner: m[1], repo: m[2], number: m[3] };
}

/**
 * Fetch the head branch of a GitHub PR via the REST API.
 * Returns the branch name, or null if the call fails for any reason.
 * Synchronous (uses spawnSync) to keep the enforcer pure-synchronous.
 */
export function fetchPrHeadBranch(
  owner: string,
  repo: string,
  number: string,
  token: string,
): string | null {
  const result = spawnSync(
    "curl",
    [
      "-s",
      "-H", "Accept: application/vnd.github+json",
      "-H", `Authorization: Bearer ${token}`,
      "-H", "X-GitHub-Api-Version: 2022-11-28",
      `https://api.github.com/repos/${owner}/${repo}/pulls/${number}`,
    ],
    { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
  );
  if (result.error || !result.stdout?.trim()) return null;
  try {
    const pr = JSON.parse(result.stdout) as { head?: { ref?: string } };
    return pr.head?.ref ?? null;
  } catch {
    return null;
  }
}

// ── Main export ───────────────────────────────────────────────────────────────

/**
 * Enforce pr_url correctness on in_review results.
 *
 * Check order:
 *   1. pr_url must be present and non-empty → blocked(pr_url_missing)
 *   2. (ctx) pr_url must parse as a valid GitHub PR URL → blocked(pr_url_unparseable)
 *   3. (ctx) owner/repo must match expectedOwner/expectedRepo → blocked(pr_url_wrong_repo)
 *   4. (ctx + githubToken) head branch must be feature/{featureId}-{taskId}
 *      → blocked(pr_url_wrong_branch). Skipped on API error (fail-open).
 *
 * Pure: does not mutate the input.
 */
export function enforceInReviewRequiresPrUrl(
  result: ExecutorResult,
  ctx?: PrUrlCtx,
): EnforceResult {
  if (result.terminal_status !== "in_review") {
    return { result, rewritten: false };
  }

  const rawUrl = result.pr_url?.trim() ?? "";

  // Check 1: URL must be present.
  if (!rawUrl) {
    return {
      result: {
        ...result,
        terminal_status: "blocked",
        blocked_reason: REWRITE_BLOCKED_REASON,
        blocked_suggestion: REWRITE_BLOCKED_SUGGESTION,
        pr_url: undefined,
      },
      rewritten: true,
    };
  }

  // Checks 2-4 require context.
  if (!ctx) {
    return { result, rewritten: false };
  }

  // Check 2: URL must parse as a GitHub PR URL.
  const coords = parsePrUrl(rawUrl);
  if (!coords) {
    return {
      result: {
        ...result,
        terminal_status: "blocked",
        blocked_reason: "pr_url_unparseable",
        blocked_suggestion:
          `pr_url "${rawUrl}" is not a valid GitHub PR URL. ` +
          "Expected format: https://github.com/{owner}/{repo}/pull/{n}. " +
          "Ensure pr-create was invoked and wrote a valid PR URL to result.json.",
        pr_url: undefined,
      },
      rewritten: true,
    };
  }

  // Check 3: owner/repo must match the task's implementation repo.
  const ownerMatch = coords.owner.toLowerCase() === ctx.expectedOwner.toLowerCase();
  const repoMatch = coords.repo.toLowerCase() === ctx.expectedRepo.toLowerCase();
  if (!ownerMatch || !repoMatch) {
    return {
      result: {
        ...result,
        terminal_status: "blocked",
        blocked_reason: "pr_url_wrong_repo",
        blocked_suggestion:
          `pr_url points to ${coords.owner}/${coords.repo} but the task targets ` +
          `${ctx.expectedOwner}/${ctx.expectedRepo}. ` +
          "Ensure pr-create was run against the correct implementation repo and " +
          "wrote the resulting URL to result.json.",
        pr_url: undefined,
      },
      rewritten: true,
    };
  }

  // Check 4: head branch must be feature/{featureId}-{taskId} (API-verified).
  if (ctx.githubToken) {
    const expectedBranch = `feature/${ctx.featureId}-${ctx.taskId}`;
    const headBranch = fetchPrHeadBranch(
      coords.owner,
      coords.repo,
      coords.number,
      ctx.githubToken,
    );
    // Fail-open: if the API is unreachable or returns null, skip the check.
    if (headBranch !== null && headBranch !== expectedBranch) {
      return {
        result: {
          ...result,
          terminal_status: "blocked",
          blocked_reason: "pr_url_wrong_branch",
          blocked_suggestion:
            `PR #${coords.number} in ${coords.owner}/${coords.repo} has head branch ` +
            `"${headBranch}" but expected "${expectedBranch}". ` +
            "This usually means the agent linked a PR from a different task or feature. " +
            "Open a PR from the correct task branch and write its URL to result.json.",
          pr_url: undefined,
        },
        rewritten: true,
      };
    }
  }

  return { result, rewritten: false };
}

