export function buildGitEnv(
  sshKeyPath: string | undefined,
  identity?: { email: string; name: string },
): NodeJS.ProcessEnv {
  return {
    ...process.env,
    ...(identity && {
      GIT_AUTHOR_NAME: identity.name,
      GIT_AUTHOR_EMAIL: identity.email,
      GIT_COMMITTER_NAME: identity.name,
      GIT_COMMITTER_EMAIL: identity.email,
    }),
    // Explicitly override inherited GIT_SSH_COMMAND: set it when a key is provided,
    // clear it otherwise so inherited env does not leak into git operations.
    GIT_SSH_COMMAND: sshKeyPath
      ? `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new`
      : undefined,
  };
}

